func loadLivestreamsByIDs(ctx context.Context, ids []int64) error {
	if len(ids) == 0 {
		return nil
	}
	wanted := make(map[int64]struct{}, len(ids))
	cacheMu.RLock()
	for _, id := range ids {
		if _, ok := livestreamByID[id]; !ok {
			wanted[id] = struct{}{}
		}
	}
	cacheMu.RUnlock()
	if len(wanted) == 0 {
		return nil
	}
	missing := make([]int64, 0, len(wanted))
	for id := range wanted {
		missing = append(missing, id)
	}

	var models []LivestreamModel
	q, args, err := sqlx.In("SELECT * FROM livestreams WHERE id IN (?)", missing)
	if err != nil {
		return err
	}
	if err := dbConn.SelectContext(ctx, &models, dbConn.Rebind(q), args...); err != nil {
		return err
	}

	type tagRow struct {
		LivestreamID int64  `db:"livestream_id"`
		ID           int64  `db:"id"`
		Name         string `db:"name"`
	}
	var tagRows []tagRow
	q, args, err = sqlx.In(`SELECT lt.livestream_id, t.id, t.name
		FROM livestream_tags lt INNER JOIN tags t ON t.id = lt.tag_id
		WHERE lt.livestream_id IN (?) ORDER BY lt.id`, missing)
	if err != nil {
		return err
	}
	if err := dbConn.SelectContext(ctx, &tagRows, dbConn.Rebind(q), args...); err != nil {
		return err
	}
	tagMap := make(map[int64][]Tag, len(missing))
	tagIDMap := make(map[int64][]int64, len(missing))
	for _, tr := range tagRows {
		tagMap[tr.LivestreamID] = append(tagMap[tr.LivestreamID], Tag{ID: tr.ID, Name: tr.Name})
		tagIDMap[tr.LivestreamID] = append(tagIDMap[tr.LivestreamID], tr.ID)
	}

	cacheMu.Lock()
	for i := range models {
		m := models[i]
		if _, exists := livestreamByID[m.ID]; exists {
			continue
		}
		livestreamByID[m.ID] = &livestreamCacheEntry{
			Model:  m,
			Tags:   tagMap[m.ID],
			TagIDs: tagIDMap[m.ID],
		}
	}
	cacheMu.Unlock()
	return nil
}

func cacheNewLivestream(model LivestreamModel, tagIDs []int64) {
	tagModels, _ := tagModelsByIDs(context.Background(), tagIDs)
	tags := make([]Tag, 0, len(tagIDs))
	for _, id := range tagIDs {
		if t, ok := tagModels[id]; ok {
			tags = append(tags, Tag{ID: t.ID, Name: t.Name})
		}
	}
	cacheMu.Lock()
	livestreamByID[model.ID] = &livestreamCacheEntry{
		Model:  model,
		Tags:   tags,
		TagIDs: append([]int64(nil), tagIDs...),
	}
	cacheMu.Unlock()
}

func fillLivestreamResponse(ctx context.Context, id int64) (Livestream, error) {
	ls, err := getLivestreamEntry(ctx, id)
	if err != nil {
		return Livestream{}, err
	}
	owner, err := getUserEntryByID(ctx, ls.Model.UserID)
	if err != nil {
		return Livestream{}, err
	}
	return Livestream{
		ID:           ls.Model.ID,
		Owner:        fillUserResponseFromEntry(owner),
		Title:        ls.Model.Title,
		Description:  ls.Model.Description,
		PlaylistUrl:  ls.Model.PlaylistUrl,
		ThumbnailUrl: ls.Model.ThumbnailUrl,
		Tags:         append([]Tag(nil), ls.Tags...),
		StartAt:      ls.Model.StartAt,
		EndAt:        ls.Model.EndAt,
	}, nil
}

func getNGWordsForLivestream(ctx context.Context, livestreamID int64) ([]*NGWord, error) {
	ngMu.RLock()
	words, ok := ngCache[livestreamID]
	ngMu.RUnlock()
	if ok {
		return words, nil
	}
	var loaded []*NGWord
	if err := dbConn.SelectContext(ctx, &loaded, "SELECT * FROM ng_words WHERE livestream_id = ? ORDER BY created_at DESC, id DESC", livestreamID); err != nil {
		return nil, err
	}
	ngMu.Lock()
	if existing, ok2 := ngCache[livestreamID]; ok2 {
		words = existing
	} else {
		ngCache[livestreamID] = loaded
		words = loaded
	}
	ngMu.Unlock()
	return words, nil
}

func addNGWordToCache(word *NGWord) {
	ngMu.Lock()
	old := ngCache[word.LivestreamID]
	next := make([]*NGWord, 0, len(old)+1)
	next = append(next, word)
	for _, w := range old {
		if w.ID != word.ID {
			next = append(next, w)
		}
	}
	ngCache[word.LivestreamID] = next
	ngMu.Unlock()
}

func isNGWord(word string, comment string) bool {
	// The original implementation uses SQL LIKE '%word%'. These terms are
	// ordinary literal strings, so a substring check has the same result and
	// avoids a database round trip for every comment.
	return len(word) > 0 && contains(comment, word)
}

func contains(s, sub string) bool {
	if len(sub) == 0 || len(sub) > len(s) {
		return false
	}
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}

