	cacheMu.RLock()
	for _, id := range ids {
		if _, ok := livestreamByID[id]; !ok {
			wanted[id] = struct{}{}
		}
	}
	cacheMu.RUnlock()
	if len(wanted) == 0 {
		return nil
	}
	missing := make([]int64, 0, len(wanted))
	for id := range wanted {
		missing = append(missing, id)
	}

	var models []LivestreamModel
	q, args, err := sqlx.In("SELECT * FROM livestreams WHERE id IN (?)", missing)
	if err != nil {
		return err
	}
	if err := dbConn.SelectContext(ctx, &models, dbConn.Rebind(q), args...); err != nil {
		return err
	}

	type tagRow struct {
		LivestreamID int64  `db:"livestream_id"`
		ID           int64  `db:"id"`
		Name         string `db:"name"`
	}
	var tagRows []tagRow
	q, args, err = sqlx.In(`SELECT lt.livestream_id, t.id, t.name
		FROM livestream_tags lt INNER JOIN tags t ON t.id = lt.tag_id
		WHERE lt.livestream_id IN (?) ORDER BY lt.id`, missing)
	if err != nil {
		return err
	}
	if err := dbConn.SelectContext(ctx, &tagRows, dbConn.Rebind(q), args...); err != nil {
		return err
	}
	tagMap := make(map[int64][]Tag, len(missing))
	tagIDMap := make(map[int64][]int64, len(missing))
	for _, tr := range tagRows {
		tagMap[tr.LivestreamID] = append(tagMap[tr.LivestreamID], Tag{ID: tr.ID, Name: tr.Name})
		tagIDMap[tr.LivestreamID] = append(tagIDMap[tr.LivestreamID], tr.ID)
	}

	cacheMu.Lock()
	for i := range models {
		m := models[i]
		if _, exists := livestreamByID[m.ID]; exists {
			continue
		}
		livestreamByID[m.ID] = &livestreamCacheEntry{
			Model:  m,
			Tags:   tagMap[m.ID],
			TagIDs: tagIDMap[m.ID],
		}
	}
	cacheMu.Unlock()
	return nil
}

func cacheNewLivestream(model LivestreamModel, tagIDs []int64) {
	tagModels, _ := tagModelsByIDs(context.Background(), tagIDs)
	tags := make([]Tag, 0, len(tagIDs))
	for _, id := range tagIDs {
