func getNGWordsForLivestream(ctx context.Context, livestreamID int64) ([]*NGWord, error) {
	ngMu.RLock()
	words, ok := ngCache[livestreamID]
	ngMu.RUnlock()
	if ok {
		return words, nil
	}
	var loaded []*NGWord
	if err := dbConn.SelectContext(ctx, &loaded, "SELECT * FROM ng_words WHERE livestream_id = ? ORDER BY created_at DESC, id DESC", livestreamID); err != nil {
		return nil, err
	}
	ngMu.Lock()
	if existing, ok2 := ngCache[livestreamID]; ok2 {
		words = existing
	} else {
		ngCache[livestreamID] = loaded
		words = loaded
	}
	ngMu.Unlock()
	return words, nil
}

func addNGWordToCache(word *NGWord) {
	ngMu.Lock()
	old := ngCache[word.LivestreamID]
	next := make([]*NGWord, 0, len(old)+1)
	next = append(next, word)
	for _, w := range old {
		if w.ID != word.ID {
			next = append(next, w)
		}
	}
	ngCache[word.LivestreamID] = next
	ngMu.Unlock()
}

func isNGWord(word string, comment string) bool {
	// The original implementation uses SQL LIKE '%word%'. These terms are
	// ordinary literal strings, so a substring check has the same result and
	// avoids a database round trip for every comment.
	return len(word) > 0 && contains(comment, word)
}

func contains(s, sub string) bool {
	if len(sub) == 0 || len(sub) > len(s) {
		return false
	}
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}

