		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get livestream: "+err.Error())
	}

	sess, _ := session.Get(defaultSessionIDKey, c)
	userID := sess.Values[defaultUserIDKey].(int64)
	if livestream.Model.UserID != userID {
		return echo.NewHTTPError(http.StatusForbidden, "can't get other streamer's livecomment reports")
	}

	var reportModels []*LivecommentReportModel
	if err := dbConn.SelectContext(ctx, &reportModels, "SELECT * FROM livecomment_reports WHERE livestream_id = ?", livestreamID); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get livecomment reports: "+err.Error())
	}

	// Load all referenced comments and users with a few queries rather than
	// the original per-report N+1 traversal.
	commentIDs := make([]int64, 0, len(reportModels))
	userIDs := make([]int64, 0, len(reportModels))
	for _, r := range reportModels {
		commentIDs = append(commentIDs, r.LivecommentID)
		userIDs = append(userIDs, r.UserID)
	}
	var commentModels []LivecommentModel
	if len(commentIDs) > 0 {
		q, args, err := sqlx.In("SELECT * FROM livecomments WHERE id IN (?)", commentIDs)
		if err != nil {
			return echo.NewHTTPError(http.StatusInternalServerError, err.Error())
		}
		if err := dbConn.SelectContext(ctx, &commentModels, dbConn.Rebind(q), args...); err != nil {
			return echo.NewHTTPError(http.StatusInternalServerError, "failed to get livecomments: "+err.Error())
		}
	}
	for _, cm := range commentModels {
		userIDs = append(userIDs, cm.UserID)
	}
	if err := loadUsersByIDs(ctx, userIDs); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get users: "+err.Error())
	}
	lsIDs := make([]int64, 0, len(commentModels))
	for _, cm := range commentModels {
		lsIDs = append(lsIDs, cm.LivestreamID)
	}
	if err := loadLivestreamsByIDs(ctx, lsIDs); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get livestreams: "+err.Error())
	}

	commentMap := make(map[int64]Livecomment, len(commentModels))
	for _, cm := range commentModels {
		lc, err := fillLivecommentResponse(ctx, cm)
		if err != nil {
			return echo.NewHTTPError(http.StatusInternalServerError, "failed to fill livecomment: "+err.Error())
		}
		commentMap[cm.ID] = lc
	}

	reports := make([]LivecommentReport, len(reportModels))
	for i, r := range reportModels {
		reporter, err := getUserEntryByID(ctx, r.UserID)
		if err != nil {
			return echo.NewHTTPError(http.StatusInternalServerError, "failed to fill livecomment report: "+err.Error())
		}
		reports[i] = LivecommentReport{
			ID:          r.ID,
			Reporter:    fillUserResponseFromEntry(reporter),
			Livecomment: commentMap[r.LivecommentID],
			CreatedAt:   r.CreatedAt,
		}
	}
	return c.JSON(http.StatusOK, reports)
}

