	}
	if livestream.Model.UserID != userID {
		return echo.NewHTTPError(http.StatusBadRequest, "A streamer can't moderate livestreams that other streamers own")
	}

	word := &NGWord{
		UserID:       userID,
		LivestreamID: int64(livestreamID),
		Word:         req.NGWord,
		CreatedAt:    time.Now().Unix(),
	}
	rs, err := dbConn.ExecContext(ctx, "INSERT INTO ng_words(user_id, livestream_id, word, created_at) VALUES (?, ?, ?, ?)", word.UserID, word.LivestreamID, word.Word, word.CreatedAt)
	if err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to insert new NG word: "+err.Error())
	}
	wordID, err := rs.LastInsertId()
	if err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get last inserted NG word id: "+err.Error())
	}
	word.ID = wordID

	// Update the cache before the delete pass so this word is included just as
	// the original SELECT of all words for the livestream did.
	words, err := getNGWordsForLivestream(ctx, int64(livestreamID))
	if err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get NG words: "+err.Error())
	}
	addNGWordToCache(word)
	if len(words) == 0 {
		words = []*NGWord{word}
	}

	for _, ngword := range words {
		if _, err := dbConn.ExecContext(ctx, "DELETE FROM livecomments WHERE livestream_id = ? AND comment LIKE CONCAT('%', ?, '%')", livestreamID, ngword.Word); err != nil {
			return echo.NewHTTPError(http.StatusInternalServerError, "failed to delete old livecomments that hit spams: "+err.Error())
		}
	}
	// Ensure the newly inserted word is also part of the delete pass.
	if _, err := dbConn.ExecContext(ctx, "DELETE FROM livecomments WHERE livestream_id = ? AND comment LIKE CONCAT('%', ?, '%')", livestreamID, word.Word); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to delete old livecomments that hit spams: "+err.Error())
	}

	return c.JSON(http.StatusCreated, map[string]interface{}{"word_id": wordID})
}

