{"command":"cat > /tmp/isupipe-lb.conf <<'EOF'
upstream isupipe_hash {
  hash $host consistent;
  server 127.0.0.1:8080;
  server 10.0.1.76:8080;
  keepalive 256;
}

upstream isupipe_primary {
  server 127.0.0.1:8080;
  keepalive 256;
}

server {
  listen 80 default_server;
  server_name _;
  index index.html index.htm index.nginx-debian.html;
  root /var/www/html;
  location / {
    try_files $uri $uri/ =404;
  }
}

server {
  listen 443 ssl default_server;
  server_name _;
  index index.html index.htm index.nginx-debian.html;
  root /var/www/html;

  ssl_certificate     /etc/nginx/tls/_.t.isucon.dev.crt;
  ssl_certificate_key /etc/nginx/tls/_.t.isucon.dev.key;
  ssl_protocols TLSv1.3;
  ssl_prefer_server_ciphers off;

  location / {
    try_files $uri $uri/ =404;
  }
}

server {
  listen 443 ssl;
  server_name pipe.u.isucon.dev;

  ssl_certificate     /etc/nginx/tls/_.u.isucon.dev.crt;
  ssl_certificate_key /etc/nginx/tls/_.u.isucon.dev.key;
  ssl_protocols TLSv1.3;
  ssl_prefer_server_ciphers off;
  ssl_session_cache shared:SSL:10m;
  ssl_session_timeout 10m;

  client_max_body_size 10m;
  root /home/isucon/webapp/public/;
  location / {
    try_files $uri /index.html;
  }
  location /api {
    access_log off;
    add_header X-Upstream $upstream_addr always;
    proxy_http_version 1.1;
    proxy_set_header Connection "";
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_connect_timeout 5s;
    proxy_read_timeout 60s;
    proxy_pass http://isupipe_primary;
  }
}

server {
  listen 443 ssl;
  server_name u.isucon.dev;
  server_name *.u.isucon.dev;

  ssl_certificate     /etc/nginx/tls/_.u.isucon.dev.crt;
  ssl_certificate_key /etc/nginx/tls/_.u.isucon.dev.key;
  ssl_protocols TLSv1.3;
  ssl_prefer_server_ciphers off;
  ssl_session_cache shared:SSL:10m;
  ssl_session_timeout 10m;

  client_max_body_size 10m;
  root /home/isucon/webapp/public/;
  location / {
    try_files $uri /index.html;
  }
  location /api {
    access_log off;
    add_header X-Upstream $upstream_addr always;
    proxy_http_version 1.1;
    proxy_set_header Connection "";
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_connect_timeout 5s;
    proxy_read_timeout 60s;
    proxy_pass http://isupipe_hash;
  }
}
EOF
scp -q /tmp/isupipe-lb.conf s1:/tmp/isupipe-lb.conf
ssh s1 'sudo cp /tmp/isupipe-lb.conf /etc/nginx/sites-enabled/isupipe.conf; sudo nginx -t && sudo systemctl reload nginx; sudo sed -i "/ISUCON13_POWERDNS_SECONDARY_ADDRESS/d" /home/isucon/env.sh; sudo sed -i "s/^cache-ttl=.*/cache-ttl=30/; s/^negquery-cache-ttl=.*/negquery-cache-ttl=0/" /etc/powerdns/pdns.conf; sudo systemctl restart pdns; sleep 1; systemctl is-active nginx pdns; grep -E "^(cache-ttl|negquery)" /etc/powerdns/pdns.conf; tail -3 /home/isucon/env.sh'","description":"Configure nginx host split and DNS positive cache"}

