new='''	// Update the cache before the delete pass. Previous words have already
	// had their matching comments removed, so only the first moderation (or
	// the newly added word) needs to run a DELETE.
	words, err := getNGWordsForLivestream(ctx, int64(livestreamID))
	if err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get NG words: "+err.Error())
	}
	addNGWordToCache(word)

	ngMu.Lock()
	applied, firstPass := ngApplied[int64(livestreamID)]
	if !firstPass {
		applied = make(map[int64]bool)
		ngApplied[int64(livestreamID)] = applied
	}
	toApply := make([]*NGWord, 0, len(words)+1)
	if firstPass {
		for _, w := range words {
			applied[w.ID] = true
		}
		applied[word.ID] = true
		toApply = append(toApply, word)
	} else {
		if !applied[word.ID] {
			applied[word.ID] = true
			toApply = append(toApply, word)
		}
	}
	ngMu.Unlock()

	for _, ngword := range toApply {
		if _, err := dbConn.ExecContext(ctx, "DELETE FROM livecomments WHERE livestream_id = ? AND comment LIKE CONCAT('%', ?, '%')", livestreamID, ngword.Word); err != nil {
			return echo.NewHTTPError(http.StatusInternalServerError, "failed to delete old livecomments that hit spams: "+err.Error())
		}
	}

	return c.JSON(http.StatusCreated, map[string]interface{}{"word_id": wordID})'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
