		Timeout: 500 * time.Millisecond,
		Transport: &http.Transport{
			Proxy: nil,
		},
	}
	for _, peer := range strings.Split(raw, ",") {
		peer = strings.TrimSpace(peer)
		if peer == "" {
			continue
		}
		req, err := http.NewRequest(http.MethodPost, peer+path, nil)
		if err != nil {
			continue
		}
		req.Header.Set("X-Isucon-Internal", internalSecret)
		resp, err := client.Do(req)
		if err != nil {
			continue
		}
		resp.Body.Close()
	}
}'''
assert old in s
